  ) then raise exception 'Refusing nonmatching staging owner/routing or future cutoff.'; end if;
  if (select count(*) from pg_temp.staging_attendance_plan)<>3509
    or (select count(distinct tournament_id) from pg_temp.staging_attendance_plan)<>5
    or exists(select 1 from pg_temp.staging_attendance_plan where tournament_id not in(1,3,4,5,6))
    then raise exception 'Attendance plan is malformed.'; end if;

  -- Locks protect the rows selected for an update. Every pre-existing row in
  -- the nine domain tables is also fingerprinted before and after the operation.
  perform 1 from public.tournaments where id in(1,3,4,5,6) order by id for update;
  perform 1 from public.orders where id in(select order_id from pg_temp.staging_attendance_plan) order by id for update;
  perform 1 from public.passes where id in(select pass_id from pg_temp.staging_attendance_plan) order by id for update;

  for phase in 0..1 loop
    select jsonb_build_object(
      'tournaments',(select md5(coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]'::jsonb)::text) from public.tournaments x),
      'tickets',(select md5(coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]'::jsonb)::text) from public.ticket_types x),
      'orders',(select md5(coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]'::jsonb)::text) from public.orders x),
      'items',(select md5(coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]'::jsonb)::text) from public.order_items x),
      'passes',(select md5(coalesce(jsonb_agg(case when phase=1 and exists(select 1 from pg_temp.staging_attendance_plan a where a.pass_id=x.id)
        then to_jsonb(x)||jsonb_build_object('status','active') else to_jsonb(x) end order by x.id),'[]'::jsonb)::text) from public.passes x),
      'scanners',(select md5(coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]'::jsonb)::text) from public.scanner_sessions x where not(x.id=any(new_scanners))),
      'checkIns',(select md5(coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]'::jsonb)::text) from public.check_ins x where not(x.id=any(new_check_ins))),
      'manualSales',(select md5(coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]'::jsonb)::text) from public.manual_sales x),
      'emails',(select md5(coalesce(jsonb_agg(to_jsonb(x) order by x.order_id),'[]'::jsonb)::text) from public.order_email_deliveries x)
    ) into actual;
    if actual<>expected then
      raise exception 'Existing data changed: stale snapshot or unexpected mutation (phase %).',phase;
    end if;
    if phase=1 then exit; end if;

    if exists(
      select 1 from pg_temp.staging_attendance_plan a
      left join public.passes p on p.id=a.pass_id
      left join public.orders o on o.id=a.order_id
      left join public.tournaments t on t.id=a.tournament_id
      where p.id is null or o.id is null or t.id is null or t.organization_id<>1
        or t.time_zone<>'America/New_York'
        or p.order_id<>a.order_id or p.tournament_id<>a.tournament_id
        or p.ticket_type_id<>a.ticket_type_id or o.tournament_id<>a.tournament_id
        or p.status<>'active' or p.uses_allowed<>1
        or o.payment_status<>'paid' or o.amount_refunded<>0
        or o.stripe_environment<>'test'
        or o.stripe_connected_account_id is distinct from 'acct_1Tui4qBDCykX1MuY'
        or o.stripe_checkout_id is not null or o.stripe_payment_intent_id is not null or o.stripe_charge_id is not null
        or not(o.buyer_email ~ '^volume-20261017-[^@]+@example[.]com$'
          or o.buyer_email ~ '^variation-20261017-e[0-9]+@example[.]com$'
          or (a.tournament_id=5 and o.buyer_email ~ '^showcase-demo-[0-9]+@example[.]com$'))
        or exists(select 1 from public.order_email_deliveries d where d.order_id=o.id)
        or exists(select 1 from public.check_ins c where c.pass_id=p.id)
        or a.admitted_at<greatest(p.created_at,o.created_at)+interval '3 minutes'
        or a.admitted_at<p.valid_from or a.admitted_at>p.valid_until or a.admitted_at>cutoff
        or (a.admitted_at at time zone t.time_zone)::date not between t.start_date and t.end_date
        or (a.admitted_at at time zone t.time_zone)::time<time '08:00'
        or (a.admitted_at at time zone t.time_zone)::time>=time '18:00'
        or (a.tournament_id=6 and (a.admitted_at at time zone t.time_zone)::date<>date '2026-10-17')
    ) then raise exception 'An admission is outside the synthetic scope, protected, or invalidly timed.'; end if;

    for ev in select t.* from public.tournaments t where t.id in(1,3,4,5,6) order by t.id loop
      -- No raw scanner token or URL is generated/stored. These sessions are
      -- inserted already revoked and can never be used by the scanner API.
      insert into public.scanner_sessions(tournament_id,gate_name,token_hash,permissions,expires_at,
        staff_label,created_by,created_at,last_active_at,revoked_at)
      values(ev.id,'Main Entrance',md5(gen_random_uuid()::text)||md5(gen_random_uuid()::text),array['scan']::text[],
        (ev.end_date+1)::timestamp at time zone ev.time_zone,'Admission Team',owner_id,
        (ev.start_date::timestamp+interval '7 hours') at time zone ev.time_zone,
        (select max(admitted_at) from pg_temp.staging_attendance_plan where tournament_id=ev.id),
        least(cutoff,(ev.end_date+1)::timestamp at time zone ev.time_zone))
      returning id into scanner_id;
      new_scanners:=array_append(new_scanners,scanner_id);
      scanner_map:=scanner_map||jsonb_build_object(ev.id::text,scanner_id);
    end loop;

    with inserted as (
      insert into public.check_ins(pass_id,tournament_id,scanner_session_id,gate_name,result,source,created_at)
      select a.pass_id,a.tournament_id,(scanner_map->>a.tournament_id::text)::bigint,
        'Main Entrance',
        case when get_byte(decode(md5('attendance-source:'||a.pass_id::text),'hex'),0)<10
          then 'manual_check_in'::public.check_in_result else 'valid'::public.check_in_result end,
        case when get_byte(decode(md5('attendance-source:'||a.pass_id::text),'hex'),0)<10
          then 'manual' else 'camera' end,a.admitted_at
      from pg_temp.staging_attendance_plan a order by a.admitted_at,a.pass_id
      returning id
    ) select array_agg(id order by id) into new_check_ins from inserted;
    update public.passes p set status='checked_in'
      from pg_temp.staging_attendance_plan a where p.id=a.pass_id and p.status='active';
  end loop;

  if cardinality(new_scanners)<>5 or cardinality(new_check_ins)<>3509
    or exists(select 1 from pg_temp.staging_attendance_plan a
      join public.passes p on p.id=a.pass_id where p.status<>'checked_in')
    or exists(select 1 from public.check_ins c where c.id=any(new_check_ins) and (
      c.source<>case when get_byte(decode(md5('attendance-source:'||c.pass_id::text),'hex'),0)<10 then 'manual' else 'camera' end
      or c.result<>case when get_byte(decode(md5('attendance-source:'||c.pass_id::text),'hex'),0)<10
        then 'manual_check_in'::public.check_in_result else 'valid'::public.check_in_result end
      or c.undone_at is not null
      or c.undone_by_scanner_session_id is not null or c.override_reason is not null
      or c.attempted_token_hash is not null
      or not exists(select 1 from pg_temp.staging_attendance_plan a where a.pass_id=c.pass_id
        and a.tournament_id=c.tournament_id and a.admitted_at=c.created_at)
      or c.scanner_session_id<>(scanner_map->>c.tournament_id::text)::bigint))
    or exists(select 1 from pg_temp.staging_attendance_plan a where
      (select count(*) from public.check_ins c where c.pass_id=a.pass_id)<>1)
    or exists(select 1 from public.scanner_sessions ss where ss.id=any(new_scanners) and (
      ss.revoked_at is null or ss.revoked_at>cutoff or ss.permissions<>array['scan']::text[]
      or ss.created_by<>owner_id or ss.gate_name<>'Main Entrance' or ss.staff_label<>'Admission Team'
      or ss.token_hash !~ '^[0-9a-f]{64}$'
      or ss.last_active_at<>(select max(admitted_at) from pg_temp.staging_attendance_plan where tournament_id=ss.tournament_id)
      or ss.created_at>(select min(admitted_at) from pg_temp.staging_attendance_plan where tournament_id=ss.tournament_id)
      or ss.expires_at<=ss.last_active_at or ss.revoked_at<ss.last_active_at))
    or exists(
      select 1 from(values(1,867),(3,927),(4,894),(5,861),(6,577)) target(event_id,total)
      where target.total<>(select count(distinct c.pass_id)
        from public.check_ins c join public.passes p on p.id=c.pass_id join public.orders o on o.id=p.order_id
        where c.tournament_id=target.event_id and c.undone_at is null
          and c.result in('valid','manual_check_in','override') and p.status in('active','checked_in')
          and o.payment_status in('paid','partial_refund')))
    then raise exception 'Final attendance/session/integrity verification failed.'; end if;
end;
$attendance$;
commit;

-- Read-only result summary. All added historical rows are synthetic admissions;
-- simulated camera/manual categories are NOT completed optical scan tests.
select t.id,t.name,
  count(distinct c.pass_id) filter(where c.undone_at is null and c.result in('valid','manual_check_in','override')
    and p.status in('active','checked_in') and o.payment_status in('paid','partial_refund')) as checked_in_passes
from public.tournaments t left join public.check_ins c on c.tournament_id=t.id
left join public.passes p on p.id=c.pass_id left join public.orders o on o.id=p.order_id
where t.id in(1,3,4,5,6) group by t.id,t.name order by t.id;
